#define main offline_embedded_main
#include "../merkle_hnsw/offline_evidence_selection.cpp"
#undef main
namespace {size_t pc(size_t n,const std::vector<int>&s){if(!n)return 0;size_t p=1;while(p<n)p<<=1;std::vector<size_t>c;for(int x:s)if(x>=0&&size_t(x)<n)c.push_back(x);std::sort(c.begin(),c.end());c.erase(std::unique(c.begin(),c.end()),c.end());if(c.empty())return 1;size_t a=0;while(p>1){std::vector<size_t>u;for(size_t i=0;i<c.size();){size_t x=c[i];if(i+1<c.size()&&c[i+1]==(x^1U))i+=2;else{++a;++i;}size_t z=x>>1;if(u.empty()||u.back()!=z)u.push_back(z);}c.swap(u);p>>=1;}return a;}}
int main()try{using namespace vann;Config c;c.cache="../merkle_hnsw/sift100k_M16_efc100.index";Matrix xb=read_fvecs(c.data+"/sift_base.fvecs",c.base),xq=read_fvecs(c.data+"/sift_query.fvecs",c.queries);HnswIndex h=build_hnsw(xb,c.M,c.efc,c.cache);xb.values.clear();xb.values.shrink_to_fit();SQIntervals sq(h);double sp=0,spr=0,rp=0,rpr=0,ap=0,apr=0,meta=0,raw=0;
for(int qi=0;qi<c.queries;++qi){XTrace t=exact_trace(h,xq.row(qi),c.ef,c.k);std::vector<Interval>in(h.size());for(int id:t.disclosed)in[id]=sq.get(xq.row(qi),id,6);Problem p=make_problem(h,t,in);Cover g=greedy(p,h.size()),m=matching(p,h.size());auto selected=selection(p,g.ids.size()<=m.ids.size()?g:m);std::vector<int>exact;for(size_t id=0;id<selected.size();++id)if(selected[id])exact.push_back(id);raw+=exact.size();sp+=t.disclosed.size()*96.0;spr+=pc(h.size(),t.disclosed)*32.0;rp+=exact.size()*h.dimension()*4.0;rpr+=pc(h.size(),exact)*32.0;meta+=32+t.disclosed.size()*4.0+exact.size()*4.0+t.expanded.size()*8.0;for(int id:t.expanded){int levels=h.index->hnsw.levels[id];for(int l=0;l<levels;++l){meta+=5;if(opened(t.opened,id,l))ap+=h.neighbors(id,l).size()*4.0;else apr+=32;}}apr+=pc(h.size(),t.expanded)*32.0;}
double nq=c.queries,proof=spr+rpr+apr,total=proof+sp+rp+ap+meta;auto k=[&](double x){return x/nq/1024;};std::cout<<"avg_raw,sq6_payload_kib,sq6_proof_kib,raw_payload_kib,raw_proof_kib,adjacency_payload_kib,adjacency_proof_kib,ids_metadata_kib,total_merkle_proof_kib,total_vo_kib\n"<<raw/nq<<','<<k(sp)<<','<<k(spr)<<','<<k(rp)<<','<<k(rpr)<<','<<k(ap)<<','<<k(apr)<<','<<k(meta)<<','<<k(proof)<<','<<k(total)<<'\n';return 0;}catch(const std::exception&e){std::cerr<<"error: "<<e.what()<<'\n';return 1;}
